PRAGMA foreign_keys = ON;

INSERT OR REPLACE INTO system_context(context_key,category,content,priority,active,updated_at) VALUES
('pwa_canonical_registry','project','CANONICAL PWA REGISTRY: Exactly three installable PWAs are authorized unless Héctor explicitly authorizes a new installable PWA: (1) Héctor OS at /; (2) Héctor Agent at /agent/; (3) Pendientes at /turno-rx/. Héctor Bridge and Context Hub are shared capabilities, not additional installable PWAs. Cross-chat claims are advisory presence signals and do not lock work, but changing the installable PWA set is a separate architectural boundary that requires explicit user authorization. Source of truth: config/pwa-registry.json.',5,1,CURRENT_TIMESTAMP),
('pwa_creation_governance','rules','PWA CREATION GOVERNANCE: Authorization to implement a feature is NOT authorization to create another installable PWA. A new installable PWA requires explicit user authorization, approvedNewPwa=true, a non-empty approvalReason, a unique non-overlapping service-worker scope, and a registry update in the same change. Reuse Héctor OS, Héctor Agent or Pendientes when the requested capability fits. Cross-chat claims remain advisory and must not block otherwise authorized work.',5,1,CURRENT_TIMESTAMP),
('cross_chat_sync_protocol','rules','CROSS-CHAT SYNC PROTOCOL: bootstrap shared context before substantial work, announce scopes with advisory claims, compare overlapping work, and commit structured handoffs after meaningful work. Claims are not locks. This non-blocking coordination rule does not override separate explicit-authorization boundaries such as creation of a new installable PWA.',5,1,CURRENT_TIMESTAMP);
